export class Pathurizer{static parse(url,directorySeparator=""){return new Pathurizer(url,directorySeparator)}constructor(url,directorySeparator=""){this.directorySeparator=directorySeparator;if(!directorySeparator){const slashIndex=url.indexOf("/");const backslashIndex=url.indexOf("\\");if(slashIndex>=0&&backslashIndex<0)this.directorySeparator="/";else if(slashIndex<0&&backslashIndex>=0)this.directorySeparator="\\";directorySeparator=this.directorySeparator}this.protocol="";this.host="";this.port="";this.root="";this.trailing="";this.directories=[];this.extension="";this.ignoreExtension="";this.params={};this.fragment="";const hashIndex=url.lastIndexOf("#");const queryIndex=url.indexOf("?");let query="";let hash="";if(hashIndex>=0){hash=url.substring(hashIndex+1);url=url.substring(0,hashIndex)}if(queryIndex>=0){query=url.substring(queryIndex+1);url=url.substring(0,queryIndex)}if(url.charAt(url.length-1)===directorySeparator)this.trailing=directorySeparator;const schemeIndex=url.indexOf("://");if(schemeIndex>=0){this.protocol=url.substring(0,schemeIndex);url=url.substring(schemeIndex+3)}const portIndex=url.indexOf(":",2);const slashIndex=url.indexOf(directorySeparator);if(portIndex>=0&&(slashIndex<0||portIndex<slashIndex)){this.host=url.substring(0,portIndex);this.port=url.substring(portIndex+1,slashIndex);url=url.substring(slashIndex+1)}else if(slashIndex>=0){if(slashIndex>0)this.host=url.substring(0,slashIndex);else this.root=url.substring(0,1);url=url.substring(slashIndex+1)}else{this.host=url;url=""}const pathSegments=url.split(directorySeparator);this.fileName=pathSegments.pop();this.directories=this.directories.concat(pathSegments.filter(segment=>segment.length>0));const paramPairs=query.length>0?query.split("&"):[];for(let i=0;i<paramPairs.length;i++){const pair=paramPairs[i].split("=");if(pair.length===2){this.params[decodeURIComponent(pair[0])]=decodeURIComponent(pair[1])}else if(pair.length===1){this.params[decodeURIComponent(pair[0])]=""}}this.fragment=decodeURIComponent(hash)}get fileName(){return this.ignoreExtension+(this.extension?"."+this.extension:"")}set fileName(value){const dotIndex=value.lastIndexOf(".");if(dotIndex>=0){this.ignoreExtension=value.substring(0,dotIndex);this.extension=value.substring(dotIndex+1)}else{this.ignoreExtension=value;this.extension=""}}get toHost(){return(this.protocol?this.protocol+":"+this.directorySeparator+this.directorySeparator:"")+this.host}get toDomain(){return this.toHost}get toPortNumber(){return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")}get toDirectories(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+this.trailing}get toFileName(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+(this.fileName?(this.directories.length||this.host?sep:"")+this.fileName:"")+this.trailing}get toFileNameIgnoreExtension(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+(this.ignoreExtension?(this.directories.length||this.host?sep:"")+this.ignoreExtension:"")+this.trailing}get toExtension(){return this.toFileName}get toParamsIgnoreFragment(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+(this.fileName?(this.directories.length||this.host?sep:"")+this.fileName:"")+this.trailing+(Object.keys(this.params).length?"?"+(()=>{let str="";for(const key in this.params){str+=key+"="+this.params[key]+"&"}str=str.slice(0,-1);return str})():"")}get toFragmentIgnoreParams(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+(this.fileName?(this.directories.length||this.host?sep:"")+this.fileName:"")+this.trailing+(this.fragment?"#"+this.fragment:"")}get url(){const sep=this.directorySeparator;return(this.protocol?this.protocol+"://":"")+this.host+(this.port?":"+this.port:"")+this.root+(this.directories.length?(this.host?sep:"")+this.directories.join(sep):"")+(this.fileName?(this.directories.length||this.host?sep:"")+this.fileName:"")+this.trailing+(Object.keys(this.params).length?"?"+(()=>{let str="";for(const key in this.params){str+=key+"="+this.params[key]+"&"}str=str.slice(0,-1);return str})():"")+(this.fragment?"#"+this.fragment:"")}get domain(){return this.host}set domain(value){this.host=value}clone(){return new Pathurizer(this.url,this.directorySeparator)}}